CREATE TABLE "places" ("id" TEXT NOT NULL, "place_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "preparation_schedules" ("id" TEXT NOT NULL, "schedule_id" TEXT NOT NULL REFERENCES schedules (id), "preparation_name" TEXT NOT NULL, "preparation_time" INTEGER NOT NULL, "next_preparation_id" TEXT NULL REFERENCES preparation_schedules (id), PRIMARY KEY ("id"));
CREATE TABLE "preparation_template_steps" ("id" TEXT NOT NULL, "template_id" TEXT NOT NULL REFERENCES preparation_templates (id), "preparation_name" TEXT NOT NULL, "preparation_time" INTEGER NOT NULL, "position" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "preparation_templates" ("id" TEXT NOT NULL, "template_name" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "preparation_users" ("id" TEXT NOT NULL, "user_id" TEXT NOT NULL REFERENCES users (id), "preparation_name" TEXT NOT NULL, "preparation_time" INTEGER NOT NULL, "next_preparation_id" TEXT NULL REFERENCES preparation_users (id), PRIMARY KEY ("id"));
CREATE TABLE "schedules" ("id" TEXT NOT NULL, "place_id" TEXT NOT NULL REFERENCES places (id), "schedule_name" TEXT NOT NULL, "time_zone_id" TEXT NOT NULL DEFAULT 'UTC', "occurrence_offset_seconds" INTEGER NULL, "schedule_time" TEXT NOT NULL, "move_time" INTEGER NOT NULL, "is_changed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_changed" IN (0, 1)), "is_started" INTEGER NOT NULL DEFAULT 0 CHECK ("is_started" IN (0, 1)), "schedule_spare_time" INTEGER NULL, "schedule_note" TEXT NULL, "lateness_time" INTEGER NOT NULL DEFAULT -1, "done_status" TEXT NOT NULL DEFAULT 'notEnded', "started_at" INTEGER NULL, "finished_at" INTEGER NULL, "preparation_mode" TEXT NULL, "preparation_template_id" TEXT NULL, "preparation_template_name" TEXT NULL, "preparation_template_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("preparation_template_deleted" IN (0, 1)), "preparation_frozen" INTEGER NOT NULL DEFAULT 0 CHECK ("preparation_frozen" IN (0, 1)), "score_contribution_recorded" INTEGER NOT NULL DEFAULT 0 CHECK ("score_contribution_recorded" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "users" ("id" TEXT NOT NULL, "spare_time" INTEGER NOT NULL, "note" TEXT NOT NULL, "is_onboarding_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_onboarding_completed" IN (0, 1)), "eligible_outcome_count" INTEGER NOT NULL DEFAULT 0, "on_time_outcome_count" INTEGER NOT NULL DEFAULT 0, "alarms_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("alarms_enabled" IN (0, 1)), "alarm_offset_minutes" INTEGER NOT NULL DEFAULT 0, "detailed_notification_content" INTEGER NOT NULL DEFAULT 0 CHECK ("detailed_notification_content" IN (0, 1)), "data_revision" INTEGER NOT NULL DEFAULT 0, "last_exported_revision" INTEGER NULL, "last_exported_at" INTEGER NULL, "first_durable_data_at" INTEGER NULL, "last_durable_data_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE INDEX preparation_schedules_next_preparation_id_idx ON preparation_schedules (next_preparation_id);
CREATE INDEX preparation_schedules_schedule_id_idx ON preparation_schedules (schedule_id);
CREATE INDEX preparation_template_steps_template_id_idx ON preparation_template_steps (template_id);
CREATE INDEX preparation_users_next_preparation_id_idx ON preparation_users (next_preparation_id);
CREATE INDEX preparation_users_user_id_idx ON preparation_users (user_id);
CREATE INDEX schedules_place_id_idx ON schedules (place_id);
CREATE INDEX schedules_schedule_time_idx ON schedules (schedule_time);
PRAGMA user_version=1;
